class Solution {
    public int finalValueAfterOperations(String[] operations) {
        int x = 0;
        for (String op : operations) {
            x += op.charAt(1) == '+' ? 1 : -1;
        }
        return x;
    }
}

class Solution {
    public int finalValueAfterOperations(String[] operations) {
        int x = 0;
        for (String op : operations) {
            switch (op) {
                case "++X":
                case "X++":
                    x++;
                    break;
                case "--X":
                case "X--":
                    x--;
                    break;
                default:
                    throw new IllegalArgumentException(op);
            }
        }
        return x;
    }
}

class Solution {
    public int finalValueAfterOperations(String[] operations) {
        int increments = 0;
        for (String op : operations) {
            if (op.charAt(1) == '+') {
                increments++;
            }
        }
        int decrements = operations.length - increments;
        return increments - decrements;
    }
}

import java.util.Map;

class Solution {
    public int finalValueAfterOperations(String[] operations) {
        Map<String, Integer> delta = Map.of(
                "++X", 1,
                "X++", 1,
                "--X", -1,
                "X--", -1);
        int x = 0;
        for (String op : operations) {
            x += delta.get(op);
        }
        return x;
    }
}
